//! 🧪️ Entity SELECT membership remains original source authority behind the ordinary exact Reference input.
use super::*;
use semio_framework_plugin::{AppRenderOperationContext,ChildContentView};
use semio_framework_ui_contract::{Component,OriginalBuiltTreeRetirement};
use semio_s_artifact_stdio_ifc_4_model::standards::v4::subsets::any::schema::snapshot::{IfcEntity,IfcComplexType,IfcTypedValue};
fn reference_value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"derived"=>IfcValue::Derived,"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"string"=>IfcValue::String(row["value"].as_str().unwrap().into()),"enum"=>IfcValue::Enum(row["value"].as_str().unwrap().into()),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(reference_value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(reference_value).collect()}),_=>panic!("closed source fixture")}}
#[test]
fn donated_reference_select_controls_use_actual_source_subtypes_without_fabricated_entity_tags(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🔎️details/🧪️tests/type-reference-select-input.json")).unwrap();for row in law["cases"].as_array().unwrap(){for supplied in [false,true]{let domain=law["domains"].as_array().unwrap().iter().find(|domain|domain["source"]==row["source"]).unwrap();let snapshot=std::sync::Arc::new(IfcSnapshot{entities:law["sources"][row["source"].as_str().unwrap()]["entities"].as_array().unwrap().iter().map(|entity|IfcEntity{id:entity["id"].as_str().unwrap().parse().unwrap(),name:entity["name"].as_str().unwrap().into(),args:entity["args"].as_array().unwrap().iter().map(reference_value).collect(),complex:entity["complex"].as_array().unwrap().iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:part["args"].as_array().unwrap().iter().map(reference_value).collect()}).collect()}).collect(),..Default::default()});let history=semio_framework_plugin::HistoryView::empty();let view=staged_view();let operation=AppRenderOperationContext{app_instance_id:17,base_revision:semio_framework_job::RevisionId(0),generation:semio_framework_job::Generation(1),canonical_base_revision:[0;32],mounted_policy:semio_framework_plugin::app_testing::artifact_app_laws::fixture_mounted_policy()};let doc=semio_framework_async::poll::resolve_ready(ArtifactView::with_render_context(snapshot.as_ref(),&history,ChildContentView::EMPTY,operation,"actual-reference-select-source",None));let mut caller=OriginalWorkFixture::new();let mut work=caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::begin_render_work(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,cx)).unwrap().unwrap();let rows=if supplied{serde_json::json!([{"index":domain["index"],"value":{"kind":"reference","value":row["reference"]}}])}else{serde_json::json!([])};let mut request=staged_request(&serde_json::json!({"path":"/entities/0","value":{"$ifcType":domain["entity"],"$ifcInputs":rows}}));request.token.action=editing::SET_SNAPSHOT_VALUE_ACTION_ID.into();let mut donor=Some(request);for _ in 0..16{if caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)).unwrap().is_some(){break;}}assert!(donor.is_none());let mut output=None;for _ in 0..1000000{match caller.work_turn(staged_grant(),1000,|cx|Ok(work.render(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,&snapshot,&doc,&view,cx))).unwrap(){Ok(Some(tree))=>{output=Some(tree);break;},Ok(None)=>{},Err(_)=>panic!("reference SELECT draft stays editable: {}",row["id"])}}
  let tree=output.unwrap();let Component::Extension(status)=&tree.root.children.get(0).unwrap().component else{panic!("original status")};assert_eq!(serde_json::to_value(&status.props).unwrap()["ready"],supplied&&row["admitted"].as_bool().unwrap());assert_eq!(tree.root.children.len(),2);let field=tree.root.children.get(1).unwrap().children.get(0).unwrap();let Component::Input(props)=&field.component else{panic!("exact Reference input")};assert_eq!(props.value.as_ref(),if supplied{row["reference"].as_str().unwrap()}else{""});assert!(!field.bindings.is_empty());let mut close=OriginalBuiltTreeRetirement::new(tree.root);for _ in 0..1000000{if close.terminal_is_empty(){break;}caller.turn(staged_grant(),|cx|cx.with_original_retirement(|cx|{let demand=close.next_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|close.step(grant))?;Ok(())})).unwrap();}assert!(close.terminal_is_empty());caller.cancel().cancel_now();retire_staged(&mut caller,&mut Some(work));assert_eq!(std::sync::Arc::strong_count(&snapshot),1);caller.finish();}}
}
